export function withAnalytics<P extends object>(
  Wrapped: ComponentType<P>, event: string,
): ComponentType<P> {
  function WithAnalytics(props: P) {
    useEffect(() => { track(event); }, []);
    return <Wrapped {...props} />;              // props preserved through P
  }
  WithAnalytics.displayName = `withAnalytics(${Wrapped.displayName ?? Wrapped.name})`;
  return WithAnalytics;                          // applied once, at the export site
}

