function withSubscription<P extends object>(
  Wrapped: ComponentType<P>, select: (ds: DataSource) => Data,
) {
  return class WithSubscription extends React.Component<P> {   // owns lifecycle
    state = { data: select(DataSource) };
    componentDidMount() { DataSource.addChangeListener(this.onChange); }
    componentWillUnmount() { DataSource.removeChangeListener(this.onChange); }
    onChange = () => this.setState({ data: select(DataSource) });
    render() { return <Wrapped data={this.state.data} {...this.props} />; }
  };
}
